create table if not exists public.ils_professional_assignment_creation_gate_audit (id uuid primary key default gen_random_uuid(), work_item_id uuid, work_stream text not null, professional_user_id uuid, work_code text, decision text not null, reason_code text not null, checks jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()); alter table public.ils_professional_assignment_creation_gate_audit enable row level security; revoke all on public.ils_professional_assignment_creation_gate_audit from anon,authenticated; create or replace function public.ils_professional_assignment_creation_gate(p_work_item_id uuid,p_work_stream text,p_professional_user_id uuid,p_work_code text) returns boolean language sql security definer stable set search_path=public as $$ select case when p_work_item_id is null or p_work_stream not in ('PROFESSIONAL','B2B') or p_professional_user_id is null or p_work_code is null then false when p_work_stream='PROFESSIONAL' then exists(select 1 from public.ils_professional_work_items w join public.ils_professional_assignment_creation_gate_audit a on false where w.id=p_work_item_id and w.professional_user_id=p_professional_user_id) and exists(select 1 from public.ils_unified_assignment_decisions u where u.work_code=p_work_code and u.associate_user_id=p_professional_user_id and u.decision='ALLOW' and u.requires_professional_review=false) when p_work_stream='B2B' then exists(select 1 from public.ils_b2b_work_items w where w.id=p_work_item_id and w.professional_user_id=p_professional_user_id) and exists(select 1 from public.ils_unified_assignment_decisions u where u.work_code=p_work_code and u.associate_user_id=p_professional_user_id and u.decision='ALLOW' and u.requires_professional_review=false) else false end $$; revoke all on function public.ils_professional_assignment_creation_gate(uuid,text,uuid,text) from public,anon,authenticated; grant execute on function public.ils_professional_assignment_creation_gate(uuid,text,uuid,text) to authenticated; comment on function public.ils_professional_assignment_creation_gate(uuid,text,uuid,text) is 'ACTION 471 fail-closed assignment creation gate; requires existing work ownership plus matching ALLOW decision. Backend should additionally verify capability/role evidence before creating assignment link.'; create index if not exists idx_ils_assignment_creation_gate_audit_user on public.ils_professional_assignment_creation_gate_audit(professional_user_id,created_at desc); create index if not exists idx_ils_assignment_creation_gate_audit_work on public.ils_professional_assignment_creation_gate_audit(work_stream,work_item_id,created_at desc);